import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Feature Auctions — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"feature-auctions-01-overview-and-concepts.md","filePath":"feature-auctions-01-overview-and-concepts.md"}'),i={name:"feature-auctions-01-overview-and-concepts.md"};function n(s,e,u,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="feature-auctions-—-overview-concepts" tabindex="-1">Feature Auctions — Overview &amp; Concepts <a class="header-anchor" href="#feature-auctions-—-overview-concepts" aria-label="Permalink to &quot;Feature Auctions — Overview &amp; Concepts&quot;">​</a></h1><p><em>What they are, why they matter, and how they fit into Lodestone</em></p><hr><h2 id="what-is-a-feature-auction" tabindex="-1">What Is a Feature Auction? <a class="header-anchor" href="#what-is-a-feature-auction" aria-label="Permalink to &quot;What Is a Feature Auction?&quot;">​</a></h2><p>A Feature Auction is a virtual implementation of the classic Buy-A-Feature prioritization game. Each participant — called a buyer — is given a fixed amount of fictitious currency and invited to spend it on the Features they care about most. Because no buyer has enough currency to purchase everything, they&#39;re forced to make tradeoffs and prioritize.</p><p>The goal isn&#39;t to produce a definitive ranked list. It&#39;s to surface perspective, generate empathy, and open up conversations about priority that might otherwise never happen.</p><hr><h2 id="why-feature-auctions-exist" tabindex="-1">Why Feature Auctions Exist <a class="header-anchor" href="#why-feature-auctions-exist" aria-label="Permalink to &quot;Why Feature Auctions Exist&quot;">​</a></h2><p>One of the most common frustrations in product management is the stakeholder who questions prioritization decisions from the outside — without ever having to experience the constraints that drove them. It&#39;s easy to say &quot;why isn&#39;t X on the roadmap?&quot; when you&#39;ve never had to choose between X, Y, and Z with a fixed budget.</p><p>Feature Auctions solve this by giving stakeholders real skin in the game. When they have to spend their own (fictitious) budget, they quickly discover that choosing is hard, tradeoffs are real, and the decisions PMs make every day are more nuanced than they appear.</p><p>For the PM, the auction produces a qualitative dataset: a clear picture of what different stakeholders value, and why.</p><blockquote><p><strong>Key idea:</strong> Feature Auctions are an input, not an output. Results don&#39;t decide the roadmap — they inform it. The PM always retains judgment over what gets built.</p></blockquote><hr><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><h3 id="the-auctioneer" tabindex="-1">The Auctioneer <a class="header-anchor" href="#the-auctioneer" aria-label="Permalink to &quot;The Auctioneer&quot;">​</a></h3><p>The Lodestone member who creates and manages the auction. Any workspace member can be an auctioneer. The auctioneer sets up the auction, invites buyers, monitors participation, and interprets results.</p><h3 id="buyers" tabindex="-1">Buyers <a class="header-anchor" href="#buyers" aria-label="Permalink to &quot;Buyers&quot;">​</a></h3><p>The stakeholders invited to participate. Buyers don&#39;t need Lodestone accounts — they receive an email invitation with a link to a dedicated auction page. Buyers can be internal (sales, marketing, CS, leadership, executives) or external (customers, partners).</p><h3 id="wallet" tabindex="-1">Wallet <a class="header-anchor" href="#wallet" aria-label="Permalink to &quot;Wallet&quot;">​</a></h3><p>Each buyer is assigned a fixed amount of fictitious currency by the auctioneer. Buyers can be given different wallet amounts — this can be used to weight certain stakeholders&#39; input more heavily, or to reflect different levels of seniority or customer ARR.</p><h3 id="feature-pricing" tabindex="-1">Feature Pricing <a class="header-anchor" href="#feature-pricing" aria-label="Permalink to &quot;Feature Pricing&quot;">​</a></h3><p>The auctioneer sets a price for each Feature in the auction. Prices reflect relative weight or complexity, not real monetary value. Higher-priced Features naturally require more of a buyer&#39;s budget, making them harder to prioritize alongside other items.</p><h3 id="the-auction-dashboard" tabindex="-1">The Auction Dashboard <a class="header-anchor" href="#the-auction-dashboard" aria-label="Permalink to &quot;The Auction Dashboard&quot;">​</a></h3><p>The auctioneer&#39;s view of live and completed auction results. Shows spend per Feature, quantity purchased, and buyer participation. Results are only visible to the auctioneer — buyers cannot see each other&#39;s activity or the aggregate results.</p><hr><h2 id="what-feature-auctions-are-not" tabindex="-1">What Feature Auctions Are Not <a class="header-anchor" href="#what-feature-auctions-are-not" aria-label="Permalink to &quot;What Feature Auctions Are Not&quot;">​</a></h2><ul><li><strong>Not a binding decision.</strong> Results do not automatically update any Feature, Roadmap, or Strategy in Lodestone. Translation into plans is always manual and intentional.</li><li><strong>Not a replacement for PM judgment.</strong> The auction surfaces stakeholder sentiment — it doesn&#39;t make the call.</li><li><strong>Not a voting system.</strong> Buyers aren&#39;t casting equal votes. They&#39;re spending a constrained budget, which creates richer signal than a simple poll.</li><li><strong>Not transparent to buyers.</strong> Buyers only see their own wallet and purchases. They cannot see what others are spending or how Features are performing in aggregate.</li></ul><hr><h2 id="how-feature-auctions-relate-to-the-rest-of-lodestone" tabindex="-1">How Feature Auctions Relate to the Rest of Lodestone <a class="header-anchor" href="#how-feature-auctions-relate-to-the-rest-of-lodestone" aria-label="Permalink to &quot;How Feature Auctions Relate to the Rest of Lodestone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Relationship</th></tr></thead><tbody><tr><td>Features</td><td>Features are the items available for purchase in an auction. Auction results do not write back to Features — no fields are updated automatically.</td></tr><tr><td>Roadmaps</td><td>Auction results can inform Roadmap priorities, but the connection is manual.</td></tr><tr><td>Strategy</td><td>Results can feed into strategy discussions, but are not linked programmatically.</td></tr><tr><td>Documents</td><td>If an Opportunity Canvas exists for a Feature, buyers can view it inside the auction by clicking on that Feature.</td></tr></tbody></table><hr><h2 id="the-cultural-value-of-feature-auctions" tabindex="-1">The Cultural Value of Feature Auctions <a class="header-anchor" href="#the-cultural-value-of-feature-auctions" aria-label="Permalink to &quot;The Cultural Value of Feature Auctions&quot;">​</a></h2><p>Beyond the data they produce, Feature Auctions have a cultural impact that&#39;s worth understanding. They:</p><ul><li>Give stakeholders a meaningful voice without giving them veto power</li><li>Replace &quot;why wasn&#39;t my thing chosen?&quot; with firsthand experience of constrained decision-making</li><li>Create cross-functional understanding of what&#39;s hard to prioritize and why</li><li>Make the PM&#39;s job more visible and legible to the rest of the organization</li></ul><p>Sometimes the most valuable outcome of a Feature Auction isn&#39;t the ranked list — it&#39;s the conversation it starts.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for creating an auction, managing buyers, and interpreting results.</em></p>',37)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
